"""Canonical required-deliverables contract for Universal Worker jobs.

Validates declared deliverable names and evaluates whether required outputs
have actually been materialized.

This helper performs no repository scan, shell, Git, SQL, network, Production,
queue, dispatcher, control-plane or AI-model operation.
"""
from __future__ import annotations

import re
from dataclasses import dataclass
from typing import Any, Final


MAX_REQUIRED_DELIVERABLES: Final[int] = 128
DELIVERABLE_NAME_RE: Final = re.compile(r"^[A-Z][A-Z0-9_]{1,127}$")


@dataclass(frozen=True)
class DeliverableEvaluation:
    required: tuple[str, ...]
    completed: tuple[str, ...]
    missing: tuple[str, ...]
    complete: bool


def normalize_required_deliverables(value: Any) -> tuple[str, ...]:
    if value is None:
        return ()

    if not isinstance(value, list):
        raise ValueError("REQUIRED_DELIVERABLES_NOT_LIST")

    if not value:
        raise ValueError("REQUIRED_DELIVERABLES_EMPTY")

    if len(value) > MAX_REQUIRED_DELIVERABLES:
        raise ValueError("REQUIRED_DELIVERABLES_TOO_MANY")

    normalized: list[str] = []

    for raw in value:
        if not isinstance(raw, str):
            raise ValueError("REQUIRED_DELIVERABLE_INVALID")

        name = raw.strip().upper()

        if not DELIVERABLE_NAME_RE.fullmatch(name):
            raise ValueError("REQUIRED_DELIVERABLE_INVALID")

        if name in normalized:
            raise ValueError("REQUIRED_DELIVERABLE_DUPLICATED")

        normalized.append(name)

    return tuple(normalized)



MAX_DELIVERABLE_SELECTOR_DEPTH: Final[int] = 32


def _normalize_source(
    value: Any,
) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ValueError(
            "DELIVERABLE_SOURCE_NOT_OBJECT"
        )

    check_type = str(
        value.get("check_type") or ""
    ).strip()

    if not check_type:
        raise ValueError(
            "DELIVERABLE_SOURCE_CHECK_TYPE_REQUIRED"
        )

    occurrence = value.get("occurrence")

    if (
        not isinstance(occurrence, int)
        or isinstance(occurrence, bool)
        or occurrence < 1
    ):
        raise ValueError(
            "DELIVERABLE_SOURCE_OCCURRENCE_INVALID"
        )

    return {
        "check_type": check_type,
        "occurrence": occurrence,
    }


def _normalize_json_path(
    value: Any,
) -> list[str | int]:
    if not isinstance(value, list):
        raise ValueError(
            "DELIVERABLE_SELECTOR_PATH_NOT_LIST"
        )

    if (
        not value
        or len(value)
        > MAX_DELIVERABLE_SELECTOR_DEPTH
    ):
        raise ValueError(
            "DELIVERABLE_SELECTOR_PATH_INVALID"
        )

    normalized: list[str | int] = []

    for item in value:
        if isinstance(item, bool):
            raise ValueError(
                "DELIVERABLE_SELECTOR_PATH_ITEM_INVALID"
            )

        if isinstance(item, int):
            if item < 0:
                raise ValueError(
                    "DELIVERABLE_SELECTOR_PATH_ITEM_INVALID"
                )
            normalized.append(item)
            continue

        if isinstance(item, str):
            key = item.strip()

            if not key:
                raise ValueError(
                    "DELIVERABLE_SELECTOR_PATH_ITEM_INVALID"
                )

            normalized.append(key)
            continue

        raise ValueError(
            "DELIVERABLE_SELECTOR_PATH_ITEM_INVALID"
        )

    return normalized


def _normalize_object_field(
    value: Any,
) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ValueError(
            "DELIVERABLE_OBJECT_FIELD_NOT_OBJECT"
        )

    source = _normalize_source(
        value.get("source")
    )

    path = _normalize_json_path(
        value.get("path")
    )

    return {
        "source": source,
        "path": path,
    }


def normalize_deliverable_specs(
    value: Any,
    required_deliverables: Any,
) -> dict[str, dict[str, Any]]:
    if value is None:
        return {}

    if not isinstance(value, dict):
        raise ValueError("DELIVERABLE_SPECS_NOT_OBJECT")

    required = set(
        normalize_required_deliverables(
            required_deliverables
        )
    )

    normalized: dict[str, dict[str, Any]] = {}

    for raw_name, raw_spec in value.items():
        if not isinstance(raw_name, str):
            raise ValueError(
                "DELIVERABLE_SPEC_INVALID_NAME"
            )

        name = raw_name.strip().upper()

        if not DELIVERABLE_NAME_RE.fullmatch(name):
            raise ValueError(
                "DELIVERABLE_SPEC_INVALID_NAME"
            )

        if name not in required:
            raise ValueError(
                "DELIVERABLE_SPEC_NOT_REQUIRED"
            )

        if name in normalized:
            raise ValueError(
                "DELIVERABLE_SPEC_DUPLICATED"
            )

        if not isinstance(raw_spec, dict):
            raise ValueError(
                "DELIVERABLE_SPEC_NOT_OBJECT"
            )

        selector = raw_spec.get("selector")

        if not isinstance(selector, dict):
            raise ValueError(
                "DELIVERABLE_SELECTOR_NOT_OBJECT"
            )

        selector_type = str(
            selector.get("type") or ""
        ).strip()

        if selector_type == "json_path":
            source = _normalize_source(
                raw_spec.get("source")
            )

            path = _normalize_json_path(
                selector.get("path")
            )

            normalized[name] = {
                "source": source,
                "selector": {
                    "type": "json_path",
                    "path": path,
                },
            }
            continue

        if selector_type == "object":
            if raw_spec.get("source") is not None:
                raise ValueError(
                    "DELIVERABLE_OBJECT_SOURCE_FORBIDDEN"
                )

            fields = selector.get("fields")

            if (
                not isinstance(fields, dict)
                or not fields
            ):
                raise ValueError(
                    "DELIVERABLE_OBJECT_FIELDS_INVALID"
                )

            normalized_fields: dict[
                str,
                dict[str, Any],
            ] = {}

            for raw_field, field_spec in fields.items():
                if not isinstance(raw_field, str):
                    raise ValueError(
                        "DELIVERABLE_OBJECT_FIELD_NAME_INVALID"
                    )

                field = raw_field.strip()

                if not field:
                    raise ValueError(
                        "DELIVERABLE_OBJECT_FIELD_NAME_INVALID"
                    )

                normalized_fields[field] = (
                    _normalize_object_field(
                        field_spec
                    )
                )

            normalized[name] = {
                "selector": {
                    "type": "object",
                    "fields": normalized_fields,
                },
            }
            continue

        raise ValueError(
            "DELIVERABLE_SELECTOR_TYPE_UNSUPPORTED"
        )

    return normalized


def resolve_check_source(
    checks: Any,
    source: dict[str, Any],
) -> dict[str, Any]:
    if not isinstance(checks, list):
        raise ValueError(
            "DELIVERABLE_CHECKS_NOT_LIST"
        )

    check_type = source["check_type"]
    occurrence = source["occurrence"]

    matches = [
        check
        for check in checks
        if isinstance(check, dict)
        and str(
            check.get("type") or ""
        ).strip() == check_type
    ]

    if len(matches) < occurrence:
        raise ValueError(
            "DELIVERABLE_SOURCE_CHECK_NOT_FOUND"
        )

    return matches[occurrence - 1]


def resolve_json_path(
    payload: Any,
    path: list[str | int],
) -> Any:
    current = payload

    for item in path:
        if isinstance(item, int):
            if not isinstance(current, list):
                raise ValueError(
                    "DELIVERABLE_SELECTOR_PATH_NOT_FOUND"
                )

            if item >= len(current):
                raise ValueError(
                    "DELIVERABLE_SELECTOR_PATH_NOT_FOUND"
                )

            current = current[item]
            continue

        if not isinstance(current, dict):
            raise ValueError(
                "DELIVERABLE_SELECTOR_PATH_NOT_FOUND"
            )

        if item not in current:
            raise ValueError(
                "DELIVERABLE_SELECTOR_PATH_NOT_FOUND"
            )

        current = current[item]

    return current


def _resolve_object_selector(
    checks: Any,
    selector: dict[str, Any],
) -> dict[str, Any]:
    payload: dict[str, Any] = {}

    for field, field_spec in (
        selector["fields"].items()
    ):
        source_check = resolve_check_source(
            checks,
            field_spec["source"],
        )

        value = resolve_json_path(
            source_check,
            field_spec["path"],
        )

        if not deliverable_payload_present(value):
            raise ValueError(
                "DELIVERABLE_OBJECT_FIELD_EMPTY"
            )

        payload[field] = value

    return payload


def materialize_deliverables(
    required_deliverables: Any,
    deliverable_specs: Any,
    checks: Any,
) -> dict[str, Any]:
    specs = normalize_deliverable_specs(
        deliverable_specs,
        required_deliverables,
    )

    materialized: dict[str, Any] = {}

    for name, spec in specs.items():
        selector = spec["selector"]

        if selector["type"] == "json_path":
            source_check = resolve_check_source(
                checks,
                spec["source"],
            )

            payload = resolve_json_path(
                source_check,
                selector["path"],
            )
        elif selector["type"] == "object":
            payload = _resolve_object_selector(
                checks,
                selector,
            )
        else:
            raise ValueError(
                "DELIVERABLE_SELECTOR_TYPE_UNSUPPORTED"
            )

        if deliverable_payload_present(payload):
            materialized[name] = payload

    return materialized


def normalize_materialized_deliverables(value: Any) -> dict[str, Any]:
    if value is None:
        return {}

    if not isinstance(value, dict):
        raise ValueError("DELIVERABLES_NOT_OBJECT")

    normalized: dict[str, Any] = {}

    for raw_name, payload in value.items():
        if not isinstance(raw_name, str):
            raise ValueError("DELIVERABLE_INVALID_NAME")

        name = raw_name.strip().upper()

        if not DELIVERABLE_NAME_RE.fullmatch(name):
            raise ValueError("DELIVERABLE_INVALID_NAME")

        normalized[name] = payload

    return normalized


def deliverable_payload_present(value: Any) -> bool:
    if value is None:
        return False

    if isinstance(value, str):
        return bool(value.strip())

    if isinstance(value, (list, tuple, set, dict)):
        return bool(value)

    return True


def evaluate_deliverables(
    required_deliverables: Any,
    deliverables: Any,
) -> DeliverableEvaluation:
    required = normalize_required_deliverables(required_deliverables)

    if not required:
        return DeliverableEvaluation(
            required=(),
            completed=(),
            missing=(),
            complete=True,
        )

    materialized = normalize_materialized_deliverables(deliverables)

    completed = tuple(
        name
        for name in required
        if name in materialized
        and deliverable_payload_present(materialized[name])
    )

    missing = tuple(
        name
        for name in required
        if name not in completed
    )

    return DeliverableEvaluation(
        required=required,
        completed=completed,
        missing=missing,
        complete=not missing,
    )

import importlib.util
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]

if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from tools.mirror_sync.worker_deliverable_contract import (
    evaluate_deliverables,
    normalize_required_deliverables,
)


def test_legacy_job_without_required_deliverables_is_compatible():
    assert normalize_required_deliverables(None) == ()


def test_required_deliverables_normalize_to_uppercase():
    assert normalize_required_deliverables(
        ["executive_finding", "REUSE_MATRIX"]
    ) == (
        "EXECUTIVE_FINDING",
        "REUSE_MATRIX",
    )


def test_required_deliverables_duplicate_fails_closed():
    try:
        normalize_required_deliverables(
            ["EXECUTIVE_FINDING", "executive_finding"]
        )
    except ValueError as exc:
        assert str(exc) == "REQUIRED_DELIVERABLE_DUPLICATED"
    else:
        raise AssertionError("duplicate must fail")


def test_required_deliverables_invalid_name_fails_closed():
    try:
        normalize_required_deliverables(["free form"])
    except ValueError as exc:
        assert str(exc) == "REQUIRED_DELIVERABLE_INVALID"
    else:
        raise AssertionError("invalid name must fail")


def test_missing_deliverable_is_detected():
    evaluation = evaluate_deliverables(
        ["EXECUTIVE_FINDING", "REUSE_MATRIX"],
        {
            "EXECUTIVE_FINDING": {
                "finding": "present",
            },
        },
    )

    assert evaluation.complete is False
    assert evaluation.completed == ("EXECUTIVE_FINDING",)
    assert evaluation.missing == ("REUSE_MATRIX",)


def test_empty_deliverable_payload_is_not_complete():
    evaluation = evaluate_deliverables(
        ["EXECUTIVE_FINDING"],
        {
            "EXECUTIVE_FINDING": {},
        },
    )

    assert evaluation.complete is False


def test_complete_deliverables_are_complete():
    evaluation = evaluate_deliverables(
        ["EXECUTIVE_FINDING", "REUSE_MATRIX"],
        {
            "EXECUTIVE_FINDING": {
                "finding": "present",
            },
            "REUSE_MATRIX": {
                "rows": ["canonical"],
            },
        },
    )

    assert evaluation.complete is True
    assert evaluation.missing == ()


def load_module(name: str, relative: str):
    path = ROOT / relative
    spec = importlib.util.spec_from_file_location(name, path)
    assert spec and spec.loader
    module = importlib.util.module_from_spec(spec)
    sys.modules[name] = module
    spec.loader.exec_module(module)
    return module


def base_readonly_job():
    return {
        "schema": "edarsahub.worker-job.v2",
        "job_id": "DELIVERABLE-CONTRACT-TEST",
        "target_repo": "rbalam/EDARSA_HUB",
        "target_branch": "Edarsahub_Desarrollo",
        "production_allowed": False,
        "objective": "test",
        "human_summary_language": "es",
        "mode": "READ_ONLY",
        "actions": [],
        "checks": [
            {
                "type": "git_diff_check",
            }
        ],
    }


def test_bridge_accepts_valid_required_deliverables():
    bridge = load_module(
        "deliverable_bridge_valid",
        "tools/mirror_sync/universal_job_bridge.py",
    )

    job = base_readonly_job()
    job["required_deliverables"] = [
        "EXECUTIVE_FINDING",
        "REUSE_MATRIX",
    ]

    errors = bridge.validate(job)

    assert "REQUIRED_DELIVERABLE_INVALID" not in errors
    assert "REQUIRED_DELIVERABLE_DUPLICATED" not in errors


def test_bridge_rejects_duplicate_required_deliverables():
    bridge = load_module(
        "deliverable_bridge_duplicate",
        "tools/mirror_sync/universal_job_bridge.py",
    )

    job = base_readonly_job()
    job["required_deliverables"] = [
        "EXECUTIVE_FINDING",
        "executive_finding",
    ]

    errors = bridge.validate(job)

    assert "REQUIRED_DELIVERABLE_DUPLICATED" in errors


def generic_result():
    return {
        "schema": "edarsahub.worker-result.v2",
        "job_id": "DELIVERABLE-PUBLISHER-TEST",
        "status": "READ_ONLY_COMPLETE",
        "tests": "PASS",
        "quality_gate": "PASS",
        "production_touched": False,
        "blockers": [],
        "files_changed": [],
        "percent_complete": 100,
        "certification": "CERTIFIED_READ_ONLY",
        "checks": [
            {
                "type": "git_diff_check",
                "status": "PASS",
                "returncode": 0,
                "output": "",
            }
        ],
    }


def test_publisher_blocks_complete_when_required_deliverable_missing():
    publisher = load_module(
        "deliverable_publisher_missing",
        "tools/mirror_sync/universal_job_result_publisher.py",
    )

    result = generic_result()

    result["required_deliverables"] = [
        "EXECUTIVE_FINDING",
        "REUSE_MATRIX",
    ]

    result["deliverables"] = {
        "EXECUTIVE_FINDING": {
            "finding": "present",
        },
    }

    evidence = publisher.certification_evidence(result)

    assert evidence["certified"] is False
    assert evidence["certification"] == "PENDING_DELIVERABLES"
    assert evidence["work_completion"] == "PENDING_DELIVERABLES"
    assert evidence["percent_complete"] <= 95
    assert evidence["missing_deliverables"] == ["REUSE_MATRIX"]


def test_publisher_legacy_readonly_still_certifies():
    publisher = load_module(
        "deliverable_publisher_legacy",
        "tools/mirror_sync/universal_job_result_publisher.py",
    )

    result = generic_result()

    evidence = publisher.certification_evidence(result)

    assert evidence["certified"] is True
    assert evidence["certification"] == "CERTIFIED_READ_ONLY"
    assert evidence["work_completion"] == "COMPLETE"
    assert evidence["percent_complete"] == 100


def test_publisher_certifies_when_required_deliverables_complete():
    publisher = load_module(
        "deliverable_publisher_complete",
        "tools/mirror_sync/universal_job_result_publisher.py",
    )

    result = generic_result()

    result["required_deliverables"] = [
        "EXECUTIVE_FINDING",
    ]

    result["deliverables"] = {
        "EXECUTIVE_FINDING": {
            "finding": "present",
        },
    }

    evidence = publisher.certification_evidence(result)

    assert evidence["certified"] is True
    assert evidence["certification"] == "CERTIFIED_READ_ONLY"
    assert evidence["work_completion"] == "COMPLETE"
    assert evidence["percent_complete"] == 100


def test_deliverable_specs_valid_generic_contract():
