def test_deliverable_specs_must_reference_required_name():
    from tools.mirror_sync.worker_deliverable_contract import (
        normalize_deliverable_specs,
    )

    try:
        normalize_deliverable_specs(
            {
                "OTHER_OUTPUT": {
                    "source": {
                        "check_type":
                            "repository_contract_audit",
                        "occurrence": 1,
                    },
                    "selector": {
