        evaluate_deliverables,
        materialize_deliverables,
    )

    checks = [
        {
            "type": "repository_contract_audit",
            "payload": {},
        }
    ]

    materialized = materialize_deliverables(
        ["EXAMPLE_OUTPUT"],
        {
            "EXAMPLE_OUTPUT": {
                "source": {
                    "check_type":
                        "repository_contract_audit",
                    "occurrence": 1,
                },
                "selector": {
                    "type": "json_path",
                    "path": ["payload"],
                },
            }
